const DSHA_RESPONSE_LANGUAGE_POLICIES = {
	ru: "Use Russian for every user-facing response, visible reasoning or progress update, and natural-language tool-call description. Preserve commands, code, paths, identifiers, file contents, and quoted text verbatim. If the user explicitly requests another response language, follow that request for that response.",
	en: "Use English for every user-facing response, visible reasoning or progress update, and natural-language tool-call description. Preserve commands, code, paths, identifiers, file contents, and quoted text verbatim. If the user explicitly requests another response language, follow that request for that response.",
	zh: "Use Simplified Chinese for every user-facing response, visible reasoning or progress update, and natural-language tool-call description. Preserve commands, code, paths, identifiers, file contents, and quoted text verbatim. If the user explicitly requests another response language, follow that request for that response."
};
function responseLanguagePolicy() {
	const language = process.env.DSHA_UI_LANGUAGE;
	return Object.hasOwn(DSHA_RESPONSE_LANGUAGE_POLICIES, language) ? DSHA_RESPONSE_LANGUAGE_POLICIES[language] : "";
}
function renderPrompt(assembly) {
	const prompt = assembly.sections.map((section) => section.interpolate === false ? section.text : interpolate(section, assembly.variables, "section")).filter((text) => text.length > 0).join("\n\n");
	return [prompt, responseLanguagePolicy()].filter((text) => text.length > 0).join("\n\n");
}
